export default "////////////\r\n// CONSTANTS\r\n////////////\r\nconst tiltRange = 8\r\nconst zoneCount = 8\r\nconst tileCount = zoneCount-1\r\nconst cam = f.camera\r\nconst letters = 'abcdefghijklmnopqrstuvwxyz'.split('')\r\nconst vowels = 'aeiou'.split('')\r\nconst consonants = letters.filter(e => !vowels.includes(e))\r\nconst uncommonTwoLetterWords = 'aa ab ad ae ag ah ai al ar as aw ay ba bi bo ch da de di ea ed ee ef eh el em en er es et ew ex fa fe fy gi gu ho io ja jo ka ki ko ky la li lo ma mi mm mo na ne nu ny ob od oe om oo op os ou ow oy pa pe pi po qi re sh si st ta te ti ug uh um un ur us ut wo xu ya ye yu za ze zo'.split(' ')\r\nconst tileFlyInSpeed = 3\r\n\r\n////////\r\n// STATE\r\n////////\r\nvar score = 0\r\nvar remainingTileCount = 24\r\nvar zones = []\r\nvar tiles = []\r\nvar submittedWords = []\r\nvar selectedTile = null\r\nvar selectedTileDelta = v3.zero\r\nvar selectedTileZoneIndex = -1\r\nvar selectedZoneIndex = -1\r\nvar gameover = false\r\nvar finalScoreT = 0\r\nvar submittedWordXPositions = []\r\n\r\n////////////\r\n// UTILITIES\r\n////////////\r\nfunction getLetter() {\r\n    shuffle(vowels)\r\n    shuffle(consonants)\r\n    if (Random.value < 0.3)\r\n        return vowels[0]\r\n    else\r\n        return consonants[0]\r\n}\r\nfunction getColor(name) {\r\n    return f.COLOR.Child(name).SpriteRenderer().color\r\n}\r\nfunction getLetterValue(letter) {\r\n    var groupValues = [1,2,3,4,5,8,10]\r\n    var groups = [\r\n        'aeioulnstr',\r\n        'dg',\r\n        'bcmp',\r\n        'fhvwy',\r\n        'k',\r\n        'jx',\r\n        'qz'\r\n    ].map(e => e.split(''))\r\n    for (var i = 0; i < groups.length; i++) {\r\n        var group = groups[i]\r\n        if (group.includes(letter))\r\n            return groupValues[i]\r\n    }\r\n}\r\nfunction getWordValue(word) {\r\n    var rawValue = word.split('').map(e => getLetterValue(e)).reduce((e,acc) => e+acc)\r\n    return Mathf.Max(1,Mathf.Floor(rawValue*(word.length)))\r\n}\r\nfunction mouseToWorld(mousePos) {\r\n    var screenHeight = 8\r\n    var screenWidth = 8*Screen.width/Screen.height\r\n    return v(mousePos.x/Screen.width*screenWidth-screenWidth*0.5, mousePos.y/Screen.height*screenHeight, 0)\r\n}\r\nfunction getTile(gob) {\r\n    var res = tiles.filter(e => e != null && e.gob != null && e.gob == gob)\r\n    if (res.length > 0)\r\n        return res[0]\r\n    return null\r\n}\r\nfunction isValidWord(word) {\r\n    if (word.length <= 1)\r\n        return false\r\n    if (word.length == 2 && uncommonTwoLetterWords.includes(word))\r\n        return false\r\n    return IsValidWord(word)\r\n}\r\nfunction getTilePos(t) {\r\n    var i = tiles.indexOf(t)\r\n    return v(0,0.5+i,0)\r\n}\r\nfunction getGameOverTileScale(t) {\r\n    var height = Mathf.Min(0.8, (0.8*4)/submittedWords.length)\r\n    return f.tile.transform.localScale.mul(height*1.3)\r\n}\r\nfunction getGameOverTilePos(t) {\r\n    var height = Mathf.Min(0.8, (0.8*4)/submittedWords.length)\r\n    var i = submittedWords.indexOf(t.word)\r\n    var xPos = submittedWordXPositions[i]\r\n    return f.gameover.Pos().add(v(xPos,0.25,0)).sub(v(0,i*height,0))\r\n}\r\nfunction positionTile(t) {\r\n    var pos = getTilePos(t)\r\n    t.gob.Pos(pos)\r\n    t.gob.transform.localEulerAngles = v(0,0,-tiltRange*Random.value+tiltRange*0.5)\r\n}\r\nfunction makeTile(word) {\r\n    var t = {\r\n        word: word != null ? word : getLetter(),\r\n        gob: make(f.tile),\r\n        lerpT: 0,\r\n        active: false\r\n    }\r\n    updateTile(t)\r\n    return t\r\n}\r\nfunction updateTile(t) {\r\n    if (t == null)\r\n        return\r\n    \r\n    var word = t.gob.Child(\"word\").Text()\r\n    var tile = t.gob.Child(\"tile\")\r\n    var outline = t.gob.Child(\"outline\")\r\n    var score = t.gob.Child(\"score\")\r\n\r\n    var isSelected = selectedTile == t\r\n    var suffix = \"\"\r\n\r\n    // selected\r\n    if (isSelected) {\r\n        // ghost tile\r\n        if (selectedZoneIndex != selectedTileZoneIndex && (selectedZoneIndex == zoneCount-1 || tiles[selectedZoneIndex] != null)) {\r\n            var color = t.gob.Child(\"tile\").MeshRenderer().material.color\r\n            color.a = 0.2\r\n            t.gob.Child(\"tile\").MeshRenderer().material.color = color\r\n\r\n            color = word.color\r\n            color.a = 0.5\r\n            word.color = color\r\n            \r\n            color = score.Text().color\r\n            color.a = 0.5\r\n            score.Text().color = color\r\n        }\r\n        // normal tile\r\n        else {\r\n            var color = t.gob.Child(\"tile\").MeshRenderer().material.color\r\n            color.a = 1\r\n            t.gob.Child(\"tile\").MeshRenderer().material.color = color\r\n\r\n            color = word.color\r\n            color.a = 1\r\n            word.color = color\r\n            \r\n            color = score.Text().color\r\n            color.a = 1\r\n            score.Text().color = color\r\n        }\r\n    }\r\n\r\n    // not selected\r\n    else {\r\n        // append to word\r\n        var zoneIndex = tiles.indexOf(t)\r\n        if (selectedTile != null && selectedTile != t &&\r\n            selectedZoneIndex == zoneIndex) {\r\n            suffix = selectedTile.word\r\n            outline.On()    \r\n        }\r\n        else {\r\n            outline.Off()\r\n        }\r\n\r\n        // validation\r\n        var singleLetter = (word.text+suffix).length==1\r\n        if (singleLetter)\r\n            t.gob.Child(\"tile\").MeshRenderer().material.color = f.tile.Child('tile').MeshRenderer().material.color\r\n        else {\r\n            var valid = isValidWord(t.word+suffix)\r\n            var color = valid ? getColor('valid') : getColor('invalid')\r\n            t.gob.Child(\"tile\").MeshRenderer().material.color = color\r\n        }\r\n    }\r\n\r\n    // word\r\n    word.text = t.word+suffix\r\n\r\n    // tile\r\n    var margin = 0.5\r\n    var outlineMargin = 0.2\r\n    var width = word.preferredWidth+margin*2\r\n    var scale = tile.transform.localScale\r\n    scale.x = width\r\n    tile.transform.localScale = scale\r\n    outline.transform.localScale = scale.add(v(outlineMargin,outlineMargin,0))\r\n\r\n    // score\r\n    score.Text().text = \"\"+getWordValue(word.text)\r\n    var scoreMargin = 0.1\r\n    var scorePos = score.transform.localPosition\r\n    scorePos.x = width*0.5-scoreMargin\r\n    score.transform.localPosition = scorePos\r\n}\r\nfunction killTile(t) {\r\n    tiles[tiles.indexOf(t)] = null\r\n    kill(t.gob)\r\n}\r\n\r\n///////\r\n// MAIN\r\n///////\r\nfunction init() {\r\n    // setup zones\r\n    zones = range(zoneCount).map(i => {\r\n        var isHeader = i==zoneCount-1\r\n        var temp = i%2==0 ? f.zone : f.zone2\r\n        if (isHeader) temp = f.zoneheader\r\n        var zone = make(temp)\r\n        zone.Pos(v(0,0.5+i,1))\r\n        return zone\r\n    })\r\n    \r\n    // setup tiles\r\n    tiles = range(tileCount).map(_ => makeTile())\r\n    tiles.map(e => positionTile(e))\r\n\r\n    // ui\r\n    f.gameover.Off()\r\n}\r\nfunction update() {\r\n    var dt = Time.deltaTime\r\n    var mousePos = Input.mousePosition\r\n    var pos = mouseToWorld(mousePos)\r\n    // f.box.Pos(pos)\r\n\r\n    if (!gameover) {\r\n        // zones\r\n        {\r\n            selectedZoneIndex = -1\r\n\r\n            // header\r\n            var header = zones[zoneCount-1]\r\n            header.Child(\"score\").Text().text = \"\"+score\r\n            header.Child(\"cards-icon\").Child(\"tilecount\").Text().text = \"\"+remainingTileCount\r\n            header.MeshRenderer().material.color = getColor('header')\r\n            header.Child(\"cards-icon\").SpriteRenderer().color = getColor('dark')\r\n            header.Child(\"cards-icon\").Child(\"tilecount\").Text().color = getColor('dark')\r\n            header.Child(\"score\").Text().color = getColor('dark')\r\n\r\n            // reset zones\r\n            zones.map(e => {\r\n                e.Child(\"selection\").Off()\r\n            })\r\n\r\n            // select if hovering\r\n            var ray = f.camera.Cam().ScreenPointToRay(Input.mousePosition)\r\n            var hit = Raycast(ray, 100, 17)\r\n            if (hit != null) {\r\n                var zone = hit.obj.transform.gameObject\r\n                selectedZoneIndex = zones.indexOf(zone)\r\n\r\n                // header\r\n                if (selectedZoneIndex == zoneCount-1) {\r\n                    if (selectedTile != null) {\r\n                        var isValid = isValidWord(selectedTile.word)\r\n                        // speculative points for valid word\r\n                        if (isValid) {\r\n                            var wordScore = getWordValue(selectedTile.word)\r\n                            zone.Child(\"score\").Text().text = \"+\"+wordScore\r\n                            zone.Child(\"score\").Text().color = getColor('white')\r\n                            zone.Child(\"cards-icon\").SpriteRenderer().color = getColor('white')\r\n                            zone.Child(\"cards-icon\").Child(\"tilecount\").Text().color = getColor('white')\r\n                            zone.MeshRenderer().material.color = getColor('valid')\r\n                        }\r\n                        // trash word\r\n                        else {\r\n                            zone.Child(\"score\").Text().color = Color.white\r\n                            zone.Child(\"cards-icon\").SpriteRenderer().color = Color.white\r\n                            zone.Child(\"cards-icon\").Child(\"tilecount\").Text().color = Color.white\r\n                            zone.MeshRenderer().material.color = getColor('invalid')\r\n                        }\r\n                    }\r\n                }\r\n                // rest of zones\r\n                else {\r\n                    zone.Child(\"selection\").On()\r\n                }         \r\n            }\r\n        }\r\n\r\n        // grab tile\r\n        if (Input.GetMouseButtonDown(0)) {\r\n            var ray = f.camera.Cam().ScreenPointToRay(Input.mousePosition)\r\n            var hit = Raycast(ray, 100, 17)\r\n            if (hit != null) {\r\n                selectedTile = tiles[selectedZoneIndex]\r\n                if (selectedTile != null) {\r\n                    selectedTileDelta = selectedTile.gob.Pos().sub(pos)\r\n                    selectedTileDelta.z = 0\r\n                    selectedTileZoneIndex = tiles.indexOf(selectedTile)\r\n                }\r\n            }\r\n        }\r\n\r\n        // drag tile\r\n        if (Input.GetMouseButton(0) && selectedTile != null) {\r\n            var newPos = pos.add(selectedTileDelta)\r\n            newPos.z = -1\r\n            selectedTile.gob.Pos(newPos)\r\n        }\r\n\r\n        // drop tile\r\n        if (Input.GetMouseButtonUp(0) && selectedTile != null) {\r\n            // back to starting zone\r\n            if (selectedZoneIndex == selectedTileZoneIndex)\r\n                positionTile(selectedTile)\r\n            \r\n            // to header zone\r\n            else if (selectedZoneIndex == zoneCount-1) {\r\n                var isValid = isValidWord(selectedTile.word)\r\n                // score word\r\n                if (isValid) {\r\n                    score += getWordValue(selectedTile.word)\r\n                    submittedWords.push(selectedTile.word)\r\n                }\r\n                else {\r\n                }\r\n                \r\n                // trash it\r\n                tiles[selectedTileZoneIndex] = null\r\n                killTile(selectedTile)\r\n            }\r\n            \r\n            // to dest zone\r\n            else {\r\n                var destTile = tiles[selectedZoneIndex]\r\n                if (destTile == null) {\r\n                    // copy to this zone\r\n                    var copy = {\r\n                        word: selectedTile.word,\r\n                        gob: selectedTile.gob,\r\n                        lerpT: 1,\r\n                        active: true\r\n                    }\r\n                    tiles[selectedZoneIndex] = copy\r\n                    tiles[selectedTileZoneIndex] = null\r\n                    positionTile(copy)\r\n                }\r\n                else {\r\n                    // append to this zone\r\n                    destTile.word += selectedTile.word\r\n                    killTile(selectedTile)\r\n                }\r\n            }\r\n            \r\n            // reset selection state\r\n            selectedTile = null\r\n            selectedTileDelta = v3.zero\r\n            selectedTileZoneIndex = -1\r\n        }\r\n\r\n        // spawn new tiles\r\n        for (var i = 0; i < tiles.length; i++) {\r\n            if (tiles[i] == null && remainingTileCount > 0) {\r\n                var t = makeTile()\r\n                tiles[i] = t\r\n                positionTile(t)\r\n                remainingTileCount--\r\n            }\r\n        }\r\n    }\r\n\r\n    // update tiles\r\n    tiles.map(tile => {\r\n        updateTile(tile)\r\n\r\n        if (gameover) {\r\n            // gameover fly in\r\n            if (tile != null && !tile.active) {\r\n                var startPos = zones[zoneCount-1].Pos()\r\n                var toPos = getGameOverTilePos(tile)\r\n                var toScale = getGameOverTileScale(tile)\r\n                tile.lerpT += dt * tileFlyInSpeed\r\n                if (tile.lerpT > 1) {\r\n                    tile.lerpT = 1\r\n                    tile.active = true\r\n                }\r\n                var t = Mathf.Sin(tile.lerpT*Mathf.PI*0.5)\r\n                var pos = v3.Lerp(startPos, toPos, t)\r\n                var scale = v3.Lerp(v3.zero, toScale, t)\r\n                tile.gob.Pos(pos)\r\n                tile.gob.transform.localScale = scale\r\n            }\r\n        }\r\n        else {\r\n            // fly in\r\n            if (tile != null && !tile.active) {\r\n                var startPos = mouseToWorld(v(0, Screen.height))\r\n                var toPos = getTilePos(tile)\r\n                tile.lerpT += dt * tileFlyInSpeed\r\n                if (tile.lerpT > 1) {\r\n                    tile.lerpT = 1\r\n                    tile.active = true\r\n                }\r\n                var t = Mathf.Sin(tile.lerpT*Mathf.PI*0.5)\r\n                var pos = v3.Lerp(startPos, toPos, t)\r\n                var scale = v3.Lerp(v3.zero, f.tile.transform.localScale, t)\r\n                tile.gob.Pos(pos)\r\n                tile.gob.transform.localScale = scale\r\n            }\r\n        }\r\n    })\r\n\r\n    // game over\r\n    if (tiles.all(e => e == null) && !gameover) {\r\n        zones.last().Off()\r\n        f.gameover.Child(\"panel\").transform.localEulerAngles = v(0,0,-tiltRange*Random.value+tiltRange*0.5)\r\n        f.gameover.On()\r\n\r\n        // set random x positions once\r\n        submittedWordXPositions = range(submittedWords.length).map(_ => (-0.5+Random.value)*3)\r\n        submittedWordXPositions.map(e => log(e))\r\n\r\n        // show submitted words\r\n        tiles = submittedWords.map(word => {\r\n            var t = makeTile(word)\r\n            positionTile(t)\r\n            return t\r\n        })\r\n\r\n        log('game over')\r\n        gameover = true\r\n    }\r\n\r\n    if (gameover) {\r\n        finalScoreT += dt\r\n        if (finalScoreT >= 1) finalScoreT = 1\r\n        var scoreVal = Mathf.Floor(Mathf.Lerp(0,score,finalScoreT*2))\r\n        f.gameover.Child(\"panel\").Child(\"score\").Text().text = \"\"+scoreVal\r\n        \r\n        if (Input.GetMouseButtonDown(0)) {\r\n            Reload(0)            \r\n        }\r\n    }\r\n}";