mapo(editorConfigs, (id, cfg, path) => {
  if (cfg.hasOwnProperty('title')) {
    const src0 = Resources.load(path, id)                 //plist[id]
    const state0 = Resources.load(path, 'state')          //plist[`${id}_state`]
    const init_state_0 = {json: JSON.parse(state0), fields: stateFields}
    const saved_state = localStorage.getItem(id+'_state')
    const initState = saved_state != null ? {json: JSON.parse(saved_state), fields: stateFields}
                                          : init_state_0
    const folds0 = partition(JSON.parse(state0).fold, 2)
    const extensions = cfg.hasOwnProperty('extension') ? cmExtensions[cfg.extension]
                                                       : cmExtensions.none
    eds[id] = {
      ...cfg,
      id,
      src0,
      state0,
      initState,
      folds0,
      extensions,
    }
  }
})

