const Wordle = ({
}) => {
  // jotai
  const fullscreenWin = makeAtom($fullscreenWin)
  const solveTitle = makeAtom(eds.solve.$title)
  // const openingLocked = makeAtom(eds.opening.$locked)
  const openingLocked = makeAtom($wordle_locked)
  const src = {
    opening: makeAtom(eds.opening.$src),
    board: makeAtom(eds.board.$src),
    keyboard: makeAtom(eds.keyboard.$src),
    solve: makeAtom(eds.solve.$src),
  }
  const error = {
    opening: makeAtom(eds.opening.$error),
  }
  const evaling = {
    opening: makeAtom(eds.opening.$evaluating),
    board: makeAtom(eds.board.$evaluating),
    keyboard: makeAtom(eds.keyboard.$evaluating),
    solve: makeAtom(eds.solve.$evaluating),
  }

  // time
  const time = makeState(0.0)
  const seekSliderRef = useRef(null)
  const timestamp = makeAtom($wordle_timestamp)
  wordle_timestamp_listener(
    useCallback(
      (get, set, newVal, prevVal) => {
        WORDLE_TIMESTAMP = newVal
      },
      [],
    ),
  )

  // init
  useEffect(() => {
    timestamp.set(timestamp.val)
  }, [])

  /////////////
  // MAIN LOGIC
  /////////////
  useDebouncedEffect(() => {
    if (WORDLE_TIMESTAMP == null || isNaN(WORDLE_TIMESTAMP)) {
      log('WORDLE_TIMESTAMP is null')
      return
    }

    if (!openingLocked.val)
      evaling.opening.set(true)
    evaling.board.set(true)
    evaling.keyboard.set(true)
    evaling.solve.set(true)

    // FIXME switch between melofy.melofy and melofy
    // flask
    fetch('https://melofy.melofy.dev/wordle/runsolver', {
      method: "POST",
      headers: {
        'Content-Type': 'application/json',
        'Connection': 'keep-alive'
      },
      body: JSON.stringify({
        // n: timestamp.val,
        n: WORDLE_TIMESTAMP,
        // opening_str: openingLocked.val ? eds.opening.src.val.replaceAll(',','').toLowerCase()
        //                                : ''
        opening_str: openingLocked.val ? src.opening.val.replaceAll(',','').toLowerCase()
                                       : ''
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        const res = data.result
        if (res == 'busy') {
          log('WORDLE SERVER IS BUSY')
        }
        else {
          // set vals
          if (!openingLocked.val) {
            if (res.opening == null) {
              // eds.opening.error.set(true)
              // eds.opening.src.set('Post Init')
              error.opening.set(true)
              src.opening.set('Post Init')
            }
            else {
              // eds.opening.error.set(null)
              // eds.opening.src.set(res.opening.toUpperCase().split('').join(','))
              error.opening.set(null)
              src.opening.set(res.opening.toUpperCase().split('').join(','))
            }
          }
          // eds.board.src.set(res.grid)
          // eds.keyboard.src.set(res.keyboard)
          src.board.set(res.grid)
          src.keyboard.set(res.keyboard)
          if (res.solve != null && res.solve.length > 0) {
            const lastSolve = res.solve[res.solve.length-1]
            if (lastSolve?.solved == 'true') {
              // eds.solve.src.set(lastSolve.word)
              // eds.solve.titleAtom.set('Solved!')
              src.solve.set(lastSolve.word)
              solveTitle.set('Solved!')
            }
            else {
              const cands = lastSolve.cands
              // eds.solve.src.set(cands.join('\n'))
              // eds.solve.titleAtom.set(`${cands.length.toLocaleString()} Candidate${cands.length==1 ? '' : 's'}`)
              src.solve.set(cands.join('\n'))
              solveTitle.set(`${cands.length.toLocaleString()} Candidate${cands.length==1 ? '' : 's'}`)
            }
          }
          // set evaling
          evaling.opening.set(false)
          evaling.board.set(false)
          evaling.keyboard.set(false)
          evaling.solve.set(false)
        }
      })
      .catch((error) => log('wordle err',error))
  }, [openingLocked.val, timestamp.val], 100)

  const header = useMemo(() => {
    return (
      <h2>
        Wordle Solver
        {techRow('js', 'py', 'opencv')}
      </h2>
    )
  }, [])

  return (
    <>
      {/* {header} */}
      {/* <p>{EdRef(eds.solve)} {EdRef(eds.opening)} {EdRef(eds.board)} {EdRef(eds.keyboard)}<br/></p> */}
      {/* <div className='row full-height center-center'>
        <div className='row' style={{
          backgroundColor: 'lemonchiffon',
          margin: '50px',
        }}> */}
        {/* <div className='col'>
          <h2 style={{marginTop: '0px', marginBottom: '0px', textAlign: 'center'}}>Wordle Solver</h2> */}
          <div className='row'>
            <div className='col'>
              <VideoWin
                // title={'Frame '+(!isNaN(timestamp.val) ? timestamp.val : 0)}
                title='wordle_video_win'
                // title='src'
                id='wordle'
                URLS={['https://media.githubusercontent.com/media/corbinsmart/lfs/main/vid2.mp4?raw=true']}
                videoStyle={{width: '337px', height: '600px'}}
                fullscreenStyle={{marginLeft: '-5px'}}
                // baseDim={{w: 1152, h: 720}}
                fullscreenWin={fullscreenWin}
                fullscreenable={false}
                scrubbable={true}
                // timestamp={timestamp}
                $timestamp={$wordle_timestamp}
                time={time}
                loop={false}
                seekSliderRef={seekSliderRef}
                paused0={true}
              />
              <input
                ref={seekSliderRef}
                type='range'
                min='0'
                max='128.23'
                step='any'
                onChange={e => time.set(parseFloat(e.target.value))}
              />
            </div>
            <div className='col'>
              {eds.solve.ed}
            </div>
            <div className='col'>  
              {eds.opening.ed}
              {eds.board.ed}
            </div>
            <div className='col'>
              {eds.keyboard.ed}
            </div>
          </div>
          {/* <div className='row' style={{width: '850px'}}>
            <p>
              Lorem Ipsum {EdRef(eds.solve)} is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry's standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book. It has survived not only five centuries, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.
            </p>
          </div>
            {techRow('js', 'py', 'opencv')}
        </div> */}
        {/* </div> 
      </div> */}
    </>
  )
}

